import React, { useState } from 'react'
import { safeImageSource } from '../../utils/contentSafety'

const ERROR_IMG_SRC =
  'data:image/svg+xml;base64,'

export function ImageWithFallback(props: React.ImgHTMLAttributes<HTMLImageElement>) {
  const [failedSource, setFailedSource] = useState<string>()
  const { src, alt, style, className, onError, ...rest } = props
  const source = safeImageSource(src)

  return !source || failedSource === source ? (
    <div
      className={`inline-block bg-gray-100 text-center align-middle ${className ?? ''}`}
      style={style}
    >
      <div className="flex items-center justify-center w-full h-full">
        <img src={ERROR_IMG_SRC} alt={alt ? alt + ' (image unavailable)' : 'Image unavailable'} {...rest} />
      </div>
    </div>
  ) : (
    <img src={source} alt={alt} className={className} style={style} {...rest} referrerPolicy="no-referrer" onError={event => { setFailedSource(source); onError?.(event); }} />
  )
}
